<?php
declare(strict_types=1);
final class WorkIssueService {
    public static function get(int $id):array{$row=Db::one('SELECT i.*,p.identifier,p.name project_name,p.workspace_id,(SELECT name FROM work_releases WHERE id=i.fix_version_id) fix_version_name,s.name state_name,s.state_group,s.color state_color FROM work_issues i JOIN work_projects p ON p.id=i.project_id JOIN work_states s ON s.id=i.state_id WHERE i.id=?',[$id])??throw new InvalidArgumentException('Work item not found.');$row['assignees']=Db::all('SELECT p.* FROM work_people p JOIN work_issue_assignees a ON a.person_id=p.id WHERE a.issue_id=? ORDER BY p.name',[$id]);$row['labels']=Db::all('SELECT l.* FROM work_labels l JOIN work_issue_labels a ON a.label_id=l.id WHERE a.issue_id=? ORDER BY l.name',[$id]);$row['key']=$row['identifier'].'-'.$row['sequence'];return $row;}
    private static function ids(mixed $value,int $max=50):array{if(!is_array($value)||count($value)>$max)throw new InvalidArgumentException('Choose a valid list of project resources.');return array_values(array_unique(array_map(fn($id)=>record_id($id),$value)));}
    public static function save(int $project,array $data,?int $id=null):int{
        $p=WorkService::project($project);if($p['status']==='archived')throw new InvalidArgumentException('Restore this project before editing its work items.');$old=$id?self::get($id):null;if($old&&((int)$old['project_id']!==$project||$old['deleted_at']!==null||$old['archived_at']!==null))throw new InvalidArgumentException('Choose an active work item from this project.');
        $value=static fn($key,$default='')=>$data[$key]??($old[$key]??$default);$title=WorkService::text($value('title'),250,true);$description=WorkService::text($value('description'),30000);$state=optional_id($value('state_id'));if(!$state)$state=(int)(Db::one("SELECT id FROM work_states WHERE project_id=? ORDER BY (state_group='unstarted') DESC,position,id LIMIT 1",[$project])['id']??throw new InvalidArgumentException('Add a workflow state first.'));$stateRow=WorkService::scoped('work_states',$project,$state);$priority=int_range($value('priority','0'),0,4);$type=$value('issue_type','task');if(!is_string($type)||!isset(WorkService::TYPES[$type]))throw new InvalidArgumentException('Choose a valid work-item type.');$fixVersion=optional_id($value('fix_version_id'));if($fixVersion)WorkService::scoped('work_releases',$project,$fixVersion);
        $cycle=optional_id($value('cycle_id'));if($cycle)WorkService::scoped('work_cycles',$project,$cycle);$module=optional_id($value('module_id'));if($module)WorkService::scoped('work_modules',$project,$module);$parent=optional_id($value('parent_id'));if($parent){$ancestor=self::get($parent);if((int)$ancestor['project_id']!==$project||($ancestor['deleted_at']!==null&&($old['parent_id']??null)!=$parent))throw new InvalidArgumentException('Choose a parent from this project.');$visited=[];while($ancestor){if((int)$ancestor['id']===$id||isset($visited[$ancestor['id']]))throw new InvalidArgumentException('A work item cannot be its own ancestor.');$visited[$ancestor['id']]=true;$ancestor=$ancestor['parent_id']?self::get((int)$ancestor['parent_id']):null;}}
        if($type==='subtask'&&!$parent)throw new InvalidArgumentException('Choose a parent for a subtask.');
        $start=WorkService::date($value('start_date'));$due=WorkService::date($value('due_date'));if($start&&$due&&$due<$start)throw new InvalidArgumentException('Due date must be on or after the start date.');$estimate=$value('estimate');if($estimate===''||$estimate===null)$estimate=null;elseif((!is_int($estimate)&&!is_float($estimate)&&!is_string($estimate))||!is_numeric($estimate)||!is_finite((float)$estimate)||(float)$estimate<0||(float)$estimate>1000)throw new InvalidArgumentException('Estimate must be between 0 and 1000 points.');else $estimate=(float)$estimate;
        $assignees=array_key_exists('assignee_ids',$data)?self::ids($data['assignee_ids']):array_map(fn($r)=>(int)$r['id'],$old['assignees']??[]);foreach($assignees as $person)WorkService::person((int)$p['workspace_id'],$person,array_key_exists('assignee_ids',$data)&&!in_array($person,array_map(fn($row)=>(int)$row['id'],$old['assignees']??[]),true));$labels=array_key_exists('label_ids',$data)?self::ids($data['label_ids']):array_map(fn($r)=>(int)$r['id'],$old['labels']??[]);foreach($labels as $label)WorkService::scoped('work_labels',$project,$label);
        $intake=$old['intake_status']??($data['intake_status']??'accepted');if(!in_array($intake,['accepted','pending','rejected'],true))throw new InvalidArgumentException('Choose a valid intake state.');$expected=$id?int_range($data['version']??'',1,PHP_INT_MAX):null;
        return Db::tx(function()use($project,$p,$old,$id,$title,$description,$state,$stateRow,$priority,$cycle,$module,$parent,$start,$due,$estimate,$assignees,$labels,$intake,$expected,$type,$fixVersion){
            if($id){$current=self::get($id);if((int)$current['version']!==$expected)throw new InvalidArgumentException('This work item changed. Reload it before saving.');Db::run('UPDATE work_issues SET title=?,description=?,state_id=?,priority=?,issue_type=?,fix_version_id=?,cycle_id=?,module_id=?,parent_id=?,start_date=?,due_date=?,estimate=?,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=?',[$title,$description,$state,$priority,$type,$fixVersion,$cycle,$module,$parent,$start,$due,$estimate,$id]);}
            else{$sequence=(int)Db::one('SELECT next_issue FROM work_projects WHERE id=?',[$project])['next_issue'];Db::run('UPDATE work_projects SET next_issue=next_issue+1,updated_at=CURRENT_TIMESTAMP WHERE id=?',[$project]);$order=(float)(Db::one('SELECT MAX(sort_order) n FROM work_issues WHERE project_id=? AND state_id=?',[$project,$state])['n']??0)+1024;$id=Db::run('INSERT INTO work_issues(project_id,sequence,title,description,state_id,priority,cycle_id,module_id,parent_id,start_date,due_date,estimate,intake_status,sort_order,issue_type,fix_version_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$project,$sequence,$title,$description,$state,$priority,$cycle,$module,$parent,$start,$due,$estimate,$intake,$order,$type,$fixVersion]);}
            Db::run('DELETE FROM work_issue_assignees WHERE issue_id=?',[$id]);foreach($assignees as $person)Db::run('INSERT INTO work_issue_assignees(issue_id,person_id) VALUES (?,?)',[$id,$person]);Db::run('DELETE FROM work_issue_labels WHERE issue_id=?',[$id]);foreach($labels as $label)Db::run('INSERT INTO work_issue_labels(issue_id,label_id) VALUES (?,?)',[$id,$label]);WorkService::log($project,$id,$old?'issue.updated':'issue.created',$title);if($stateRow['state_group']==='completed'&&($old['state_group']??null)!=='completed')WorkService::log($project,$id,'issue.completed',$title);WorkService::snapshot($project);return $id;
        });
    }
    public static function filters(int $project,array $input):array{
        WorkService::project($project);$filters=['q'=>WorkService::text($input['q']??'',200),'priority'=>'','state'=>'','assignee'=>'','label'=>'','cycle'=>'','module'=>'','release'=>'','issue_type'=>'','scope'=>$input['scope']??'active','order'=>$input['order']??'manual','range_from'=>WorkService::date($input['range_from']??''),'range_to'=>WorkService::date($input['range_to']??''),'range_mode'=>$input['range_mode']??'due'];
        if(!in_array($filters['scope'],['active','archived','trash','intake','rejected','mine','overdue'],true)||!in_array($filters['order'],['manual','priority','updated','due'],true))throw new InvalidArgumentException('Choose valid work-item filters.');
        foreach(['priority','state','assignee','label','cycle','module','release'] as $key){$value=$input[$key]??'';if($value==='')continue;if($key==='priority')$filters[$key]=int_range($value,0,4);else{$id=record_id($value);if($key==='assignee')WorkService::person((int)WorkService::project($project)['workspace_id'],$id);else WorkService::scoped(match($key){'state'=>'work_states','label'=>'work_labels','cycle'=>'work_cycles','module'=>'work_modules','release'=>'work_releases'},$project,$id);$filters[$key]=$id;}}
        if(isset($input['issue_type'])&&$input['issue_type']!==''){$type=$input['issue_type'];if(!is_string($type)||!isset(WorkService::TYPES[$type]))throw new InvalidArgumentException('Choose a valid work-item type.');$filters['issue_type']=$type;}
        if(!in_array($filters['range_mode'],['due','overlap'],true)||($filters['range_from']&&$filters['range_to']&&$filters['range_to']<$filters['range_from']))throw new InvalidArgumentException('Choose a valid date range.');
        return $filters;
    }
    public static function listing(int $project,array $input=[],int $page=1,int $perPage=100):array{
        $filters=self::filters($project,$input);$where=['i.project_id=?'];$params=[$project];$scope=$filters['scope'];
        if($scope==='trash')$where[]='i.deleted_at IS NOT NULL';else{$where[]='i.deleted_at IS NULL';if($scope==='archived')$where[]='i.archived_at IS NOT NULL';else{$where[]='i.archived_at IS NULL';$where[]=$scope==='intake'?"i.intake_status='pending'":($scope==='rejected'?"i.intake_status='rejected'":"i.intake_status='accepted'");}}
        if($scope==='mine'){$where[]='EXISTS(SELECT 1 FROM work_issue_assignees a WHERE a.issue_id=i.id AND a.person_id=?)';$params[]=WorkService::self((int)WorkService::project($project)['workspace_id']);}if($scope==='overdue'){$where[]="i.due_date<? AND s.state_group NOT IN ('completed','cancelled')";$params[]=date('Y-m-d');}
        if($filters['range_from']){$where[]=($filters['range_mode']==='overlap'?'i.due_date':'i.due_date').'>=?';$params[]=$filters['range_from'];}if($filters['range_to']){$where[]=($filters['range_mode']==='overlap'?'i.start_date':'i.due_date').'<=?';$params[]=$filters['range_to'];}
        if($filters['q']!==''){$where[]="(instr(lower(i.title),lower(?))>0 OR instr(lower(i.description),lower(?))>0 OR (p.identifier||'-'||i.sequence)=?)";$params[]=$filters['q'];$params[]=$filters['q'];$params[]=strtoupper($filters['q']);}
        foreach(['priority'=>'i.priority','state'=>'i.state_id','cycle'=>'i.cycle_id','module'=>'i.module_id','release'=>'i.fix_version_id','issue_type'=>'i.issue_type'] as $key=>$column)if($filters[$key]!==''){$where[]=$column.'=?';$params[]=$filters[$key];}
        foreach(['assignee'=>['work_issue_assignees','person_id'],'label'=>['work_issue_labels','label_id']] as $key=>[$table,$column])if($filters[$key]!==''){$where[]="EXISTS(SELECT 1 FROM $table a WHERE a.issue_id=i.id AND a.$column=?)";$params[]=$filters[$key];}
        $from=' FROM work_issues i JOIN work_projects p ON p.id=i.project_id JOIN work_states s ON s.id=i.state_id WHERE '.implode(' AND ',$where);$total=(int)Db::one('SELECT COUNT(*) n'.$from,$params)['n'];$perPage=max(1,min(500,$perPage));$pages=max(1,(int)ceil($total/$perPage));$page=max(1,min($page,$pages));$order=match($filters['order']){'priority'=>'(i.priority=0),i.priority,i.sequence','updated'=>'i.updated_at DESC,i.id DESC','due'=>'i.due_date IS NULL,i.due_date,i.sequence',default=>'s.position,i.sort_order,i.sequence'};
        $rows=Db::all('SELECT i.*,(SELECT name FROM work_releases WHERE id=i.fix_version_id) fix_version_name,s.name state_name,s.state_group,s.color state_color,p.identifier'.$from.' ORDER BY '.$order.' LIMIT '.$perPage.' OFFSET '.(($page-1)*$perPage),$params);foreach($rows as &$row){$row['key']=$row['identifier'].'-'.$row['sequence'];$row['assignees']=Db::all('SELECT p.id,p.name FROM work_people p JOIN work_issue_assignees a ON a.person_id=p.id WHERE a.issue_id=?',[$row['id']]);$row['labels']=Db::all('SELECT l.* FROM work_labels l JOIN work_issue_labels a ON a.label_id=l.id WHERE a.issue_id=?',[$row['id']]);}unset($row);return compact('rows','total','pages','page','filters');
    }
    public static function move(int $project,int $id,int $state,int $version):void{$row=self::get($id);if((int)$row['project_id']!==$project)throw new InvalidArgumentException('Choose a work item from this project.');self::save($project,['state_id'=>$state,'version'=>$version],$id);}
    public static function lifecycle(int $project,int $id,string $action,int $version):void{
        if(!in_array($action,['archive','unarchive','trash','restore','accept','reject'],true))throw new InvalidArgumentException('Choose a valid work-item action.');Db::tx(function()use($project,$id,$action,$version){$row=self::get($id);if((int)$row['project_id']!==$project||(int)$row['version']!==$version)throw new InvalidArgumentException('This work item changed or belongs to another project.');if(Db::one('SELECT id FROM work_timers WHERE issue_id=?',[$id])&&in_array($action,['archive','trash','reject'],true))throw new InvalidArgumentException('Stop this work item’s running timer first.');$change=match($action){'archive'=>'archived_at=CURRENT_TIMESTAMP','unarchive'=>'archived_at=NULL','trash'=>'deleted_at=CURRENT_TIMESTAMP','restore'=>'deleted_at=NULL','accept'=>"intake_status='accepted'",'reject'=>"intake_status='rejected'"};Db::run('UPDATE work_issues SET '.$change.',version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=?',[$id]);WorkService::log($project,$id,'issue.'.$action,$row['title']);WorkService::snapshot($project);});
    }
    public static function bulk(int $project,array $ids,array $versions,string $field,mixed $value):void{
        $p=WorkService::project($project);if($p['status']==='archived')throw new InvalidArgumentException('Restore this project before bulk editing.');$ids=self::ids($ids,100);if(!$ids||!in_array($field,['state_id','priority','cycle_id','module_id','issue_type','fix_version_id'],true))throw new InvalidArgumentException('Select work items and an allowed bulk action.');
        // Validate all records before any change; one transaction wraps all writes.
        Db::tx(function()use($project,$ids,$versions,$field,$value){foreach($ids as $id){$row=self::get($id);if((int)$row['project_id']!==$project||(int)$row['version']!==record_id($versions[$id]??''))throw new InvalidArgumentException('A selected item changed or belongs to another project.');$normalized=$field==='priority'?int_range($value,0,4):($field==='issue_type'?WorkService::text($value,20,true):optional_id($value));if($field==='issue_type'&&(!isset(WorkService::TYPES[$normalized])||($normalized==='subtask'&&!$row['parent_id'])))throw new InvalidArgumentException('Choose a valid type; subtasks require a parent.');if($field==='state_id'&&$normalized===null)throw new InvalidArgumentException('Choose a workflow state.');if($normalized!==null&&!in_array($field,['priority','issue_type'],true))WorkService::scoped(match($field){'state_id'=>'work_states','cycle_id'=>'work_cycles','module_id'=>'work_modules','fix_version_id'=>'work_releases'},$project,$normalized);}
            foreach($ids as $id){$row=self::get($id);if($row['deleted_at']!==null||$row['archived_at']!==null)throw new InvalidArgumentException('Choose active work items.');$normalized=$field==='priority'?int_range($value,0,4):($field==='issue_type'?WorkService::text($value,20,true):optional_id($value));if($field==='issue_type'&&(!isset(WorkService::TYPES[$normalized])||($normalized==='subtask'&&!$row['parent_id'])))throw new InvalidArgumentException('Choose a valid type; subtasks require a parent.');Db::run('UPDATE work_issues SET '.$field.'=?,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=?',[$normalized,$id]);WorkService::log($project,$id,'issue.bulk_updated',$field);if($field==='state_id'&&$row['state_group']!=='completed'&&WorkService::scoped('work_states',$project,(int)$normalized)['state_group']==='completed')WorkService::log($project,$id,'issue.completed',$row['title']);}
            WorkService::snapshot($project);
        });
    }
    public static function relate(int $project,int $from,int $to,string $kind):void{
        if(!in_array($kind,['blocks','relates','duplicates'],true)||$from===$to)throw new InvalidArgumentException('Choose a different related work item and relation.');foreach([$from,$to] as $id){$row=self::get($id);if((int)$row['project_id']!==$project||$row['deleted_at']!==null)throw new InvalidArgumentException('Relations must stay in the same project.');}
        if($kind!=='blocks'&&$from>$to)[$from,$to]=[$to,$from];
        Db::tx(function()use($project,$from,$to,$kind){if($kind==='blocks'&&Db::one("WITH RECURSIVE dependencies(id) AS (SELECT to_id FROM work_relations WHERE from_id=? AND kind='blocks' UNION SELECT r.to_id FROM work_relations r JOIN dependencies d ON r.from_id=d.id WHERE r.kind='blocks') SELECT id FROM dependencies WHERE id=? LIMIT 1",[$to,$from]))throw new InvalidArgumentException('This blocking relation would create a dependency cycle.');if(Db::one('SELECT id FROM work_relations WHERE from_id=? AND to_id=? AND kind=?',[$from,$to,$kind]))throw new InvalidArgumentException('This relationship already exists.');Db::run('INSERT INTO work_relations(project_id,from_id,to_id,kind) VALUES (?,?,?,?)',[$project,$from,$to,$kind]);WorkService::log($project,$from,'issue.related',$kind.':'.self::get($to)['key']);});
    }
    public static function comment(int $issue,string $body,?int $id=null,?int $version=null):int{$item=self::get($issue);if($item['deleted_at']!==null)throw new InvalidArgumentException('Restore this work item before commenting.');$body=WorkService::text($body,20000,true);if($id){$old=Db::one('SELECT * FROM work_comments WHERE id=? AND issue_id=? AND deleted_at IS NULL',[$id,$issue]);if(!$old||(int)$old['version']!==$version)throw new InvalidArgumentException('Comment changed. Reload before editing.');Db::run('UPDATE work_comments SET body=?,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=?',[$body,$id]);}else $id=Db::run('INSERT INTO work_comments(issue_id,author_id,body) VALUES (?,?,?)',[$issue,WorkService::self((int)$item['workspace_id']),$body]);WorkService::log((int)$item['project_id'],$issue,'comment.saved','');return $id;}
    public static function logTime(int $issue,array $data):int{$row=self::get($issue);if($row['deleted_at']!==null||$row['archived_at']!==null)throw new InvalidArgumentException('Restore this work item before logging time.');$person=optional_id($data['person_id']??'')??WorkService::self((int)$row['workspace_id']);WorkService::person((int)$row['workspace_id'],$person,true);$date=valid_date(WorkService::text($data['on_date']??date('Y-m-d'),10,true));$minutes=int_range($data['minutes']??'',1,1440);$notes=WorkService::text($data['notes']??'',2000);$id=Db::run('INSERT INTO work_time_entries(issue_id,person_id,on_date,minutes,notes) VALUES (?,?,?,?,?)',[$issue,$person,$date,$minutes,$notes]);WorkService::log((int)$row['project_id'],$issue,'time.logged',$minutes.' minutes');return $id;}
    public static function startTimer(int $issue):void{$row=self::get($issue);if($row['deleted_at']!==null||$row['archived_at']!==null)throw new InvalidArgumentException('Choose an active work item.');if(Db::one('SELECT id FROM work_timers WHERE workspace_id=?',[$row['workspace_id']]))throw new InvalidArgumentException('Stop the active timer in this workspace first.');Db::run('INSERT INTO work_timers(workspace_id,issue_id,started_at) VALUES (?,?,?)',[$row['workspace_id'],$issue,time()]);}
    public static function stopTimer(int $issue,mixed $corrected=''):void{Db::tx(function()use($issue,$corrected){$row=self::get($issue);$timer=Db::one('SELECT * FROM work_timers WHERE workspace_id=? AND issue_id=?',[$row['workspace_id'],$issue]);if(!$timer)throw new InvalidArgumentException('This work item has no running timer.');$minutes=(int)ceil((time()-(int)$timer['started_at'])/60);if($corrected!=='')$minutes=int_range($corrected,1,1440);if($minutes>1440||$minutes<0)throw new InvalidArgumentException('Enter the actual minutes to correct a timer longer than 24 hours.');self::logTime($issue,['minutes'=>max(1,$minutes),'notes'=>'Recorded with the work timer; rounded up to the nearest minute.']);Db::run('DELETE FROM work_timers WHERE id=?',[$timer['id']]);});}
    public static function attach(int $issue,array $file):int{
        $row=self::get($issue);if($row['deleted_at']!==null||($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_string($file['tmp_name']??null)||!is_uploaded_file($file['tmp_name']))throw new InvalidArgumentException('Choose an attachment for an active work item.');$document=DocumentService::store($file['tmp_name'],$file['name'],$row['key'].' · '.DocumentService::downloadName($file['name']),'Other','Attached to '.$row['key'],DATA);
        try{$id=Db::run('INSERT INTO work_attachments(issue_id,document_id) VALUES (?,?)',[$issue,$document]);WorkService::log((int)$row['project_id'],$issue,'attachment.added',DocumentService::downloadName($file['name']));return $id;}catch(Throwable $e){$doc=Db::one('SELECT * FROM documents WHERE id=?',[$document]);Db::run('DELETE FROM documents WHERE id=?',[$document]);if($doc){$path=DocumentService::path($doc,DATA);if(is_file($path))unlink($path);}throw $e;}
    }
}
